import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Build the scene container
  const group = new THREE.Group();
  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Create a plane geometry for the card
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load the image texture
  let material;
  ctx.textureLoader.loadTexture(config.imageUrl).then((imageTex) => {
    // Create TSL-based material with texture sampling
    const sampledColor = texture(imageTex, uv());

    material = new MeshBasicNodeMaterial({
      colorNode: sampledColor,
      transparent: true,
      toneMapped: true,
    });

    mesh.material = material;
  });

  // Initialize with a placeholder material
  material = new MeshBasicNodeMaterial({
    color: 0x0b0b10,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.receiveShadow = false;
  mesh.castShadow = false;
  group.add(mesh);

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    if (material) material.dispose();
  };

  // No event handlers for this static composition
  group.userData.handlers = {};

  return group;
}
